public class Main {
    public static void main(String[] args) {
        String s = "babcbabcbaccba";
        // Pad with '#' so odd and even palindromes both get a centre cell.
        StringBuilder sb = new StringBuilder("#");
        for (char ch : s.toCharArray()) sb.append(ch).append('#');
        char[] t = sb.toString().toCharArray();
        int n = t.length, c = 0, r = 0, best = 0, bestC = 0;
        int[] p = new int[n];                  // p[i] = palindrome radius around cell i
        for (int i = 0; i < n; i++) {
            // Inside the box that ends at r: reuse the mirror cell, capped at the box edge.
            if (i < r) p[i] = Math.min(p[2 * c - i], r - i);
            // Expand with real comparisons; every success pushes r to the right.
            while (i - p[i] - 1 >= 0 && i + p[i] + 1 < n && t[i - p[i] - 1] == t[i + p[i] + 1]) p[i]++;
            if (i + p[i] > r) { c = i; r = i + p[i]; }
            if (p[i] > best) { best = p[i]; bestC = i; }
        }
        int start = (bestC - best) / 2;        // map the padded cell back to the text
        System.out.println("Text: " + s);
        System.out.println("Longest palindrome: " + s.substring(start, start + best) + " (length " + best + ")");
        // Time O(N): r only moves right. Space O(N) for the radius array.
    }
}

