import java.util.*;

public class Main {
    public static void main(String[] args) {
        String s = "banana";
        int n = s.length();
        Integer[] sa = new Integer[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) { sa[i] = i; rank[i] = s.charAt(i); }  // round 0: rank = first letter
        for (int k = 1; ; k *= 2) {
            final int kk = k;
            final int[] rk = rank;
            // Compare the first 2k letters using two ranks of k letters each.
            Comparator<Integer> cmp = (a, b) -> {
                if (rk[a] != rk[b]) return Integer.compare(rk[a], rk[b]);
                int ra = a + kk < n ? rk[a + kk] : -1;   // -1: the suffix ended, so it sorts first
                int rb = b + kk < n ? rk[b + kk] : -1;
                return Integer.compare(ra, rb);
            };
            Arrays.sort(sa, cmp);
            int[] next = new int[n];                      // new ranks: equal pairs share a rank
            for (int i = 1; i < n; i++)
                next[sa[i]] = next[sa[i - 1]] + (cmp.compare(sa[i - 1], sa[i]) < 0 ? 1 : 0);
            rank = next;
            if (rank[sa[n - 1]] == n - 1) break;          // all ranks different: fully sorted
        }
        System.out.println("Text: " + s);
        for (int r = 0; r < n; r++) System.out.println("rank " + r + ": start " + sa[r] + "  " + s.substring(sa[r]));
        // Time O(N log^2 N) with a comparison sort (O(N log N) with radix sort). Space O(N).
    }
}

