#include <bits/stdc++.h>
using namespace std;

int main() {
    string s = "banana";
    int n = s.size();
    vector<int> sa(n), rnk(n);
    for (int i = 0; i < n; i++) { sa[i] = i; rnk[i] = s[i]; }   // round 0: rank = first letter
    for (int k = 1; ; k *= 2) {
        // Compare the first 2k letters using two ranks of k letters each.
        auto less = [&](int a, int b) {
            if (rnk[a] != rnk[b]) return rnk[a] < rnk[b];
            int ra = a + k < n ? rnk[a + k] : -1;   // -1: the suffix ended, so it sorts first
            int rb = b + k < n ? rnk[b + k] : -1;
            return ra < rb;
        };
        sort(sa.begin(), sa.end(), less);
        vector<int> next(n, 0);                     // new ranks: equal pairs share a rank
        for (int i = 1; i < n; i++)
            next[sa[i]] = next[sa[i - 1]] + (less(sa[i - 1], sa[i]) ? 1 : 0);
        rnk = next;
        if (rnk[sa[n - 1]] == n - 1) break;         // all ranks different: fully sorted
    }
    cout << "Text: " << s << "\n";
    for (int r = 0; r < n; r++) cout << "rank " << r << ": start " << sa[r] << "  " << s.substr(sa[r]) << "\n";
    // Time O(N log^2 N) with a comparison sort (O(N log N) with radix sort). Space O(N).
    return 0;
}

