import java.util.*;

public class Main {
    public static void main(String[] args) {
        String s = "banana";
        int n = s.length();
        Integer[] sa = new Integer[n];
        for (int i = 0; i < n; i++) sa[i] = i;
        Arrays.sort(sa, (a, b) -> s.substring(a).compareTo(s.substring(b)));  // simple build, fine for a demo
        int[] rank = new int[n], lcp = new int[n];
        for (int r = 0; r < n; r++) rank[sa[r]] = r;      // rank = inverse of the suffix array
        int h = 0, matches = 0;
        for (int i = 0; i < n; i++) {                     // text order, not sorted order
            if (rank[i] == 0) { h = 0; continue; }        // no neighbour before the smallest suffix
            int j = sa[rank[i] - 1];                      // the suffix just before i in sorted order
            while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) { h++; matches++; }
            lcp[rank[i]] = h;
            if (h > 0) h--;                               // lemma: the next suffix keeps at least h - 1
        }
        StringBuilder a = new StringBuilder(), b = new StringBuilder();
        for (int r = 0; r < n; r++) { a.append(" ").append(sa[r]); b.append(" ").append(lcp[r]); }
        System.out.println("Text: " + s);
        System.out.println("SA :" + a);
        System.out.println("LCP:" + b);
        System.out.println("Letter matches: " + matches + " (never more than 2N = " + 2 * n + ")");
        // Kasai itself: time O(N), space O(N).
    }
}

