// Is there a repeat of length len whose two copies do not overlap? Returns a start or -1.
int find(const vector<int>& sa, const vector<int>& lcp, int len) {
    int mn = 0, mx = 0;
    for (int r = 0; r < (int)sa.size(); r++) {
        // Ranks joined by lcp >= len form one block: they all share the same first len letters.
        if (r > 0 && lcp[r] >= len) { mn = min(mn, sa[r]); mx = max(mx, sa[r]); }
        else { mn = sa[r]; mx = sa[r]; }
        if (mx - mn >= len) return mn;       // far enough apart: no overlap
    }
    return -1;
}

void solve(const string& s) {
    int n = s.size();
    vector<int> sa(n), lcp(n, 0);            // lcp[r]: letters shared by sorted suffixes r-1 and r
    iota(sa.begin(), sa.end(), 0);
    sort(sa.begin(), sa.end(), [&](int a, int b) {
        return s.compare(a, string::npos, s, b, string::npos) < 0;
    });
    for (int r = 1; r < n; r++) {
        int a = sa[r - 1], b = sa[r], h = 0;
        while (a + h < n && b + h < n && s[a + h] == s[b + h]) h++;
        lcp[r] = h;
    }
    int best = 0, at = 0;                    // overlap allowed: the largest lcp value
    for (int r = 1; r < n; r++) if (lcp[r] > best) { best = lcp[r]; at = sa[r]; }
    int lo = 0, hi = n / 2, start = 0;       // no overlap: binary search on the length
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2, f = find(sa, lcp, mid);
        if (f >= 0) { lo = mid; start = f; } else hi = mid - 1;
    }
    cout << s << ": overlap allowed = \"" << s.substr(at, best) << "\" (" << best
         << "), no overlap = \"" << s.substr(start, lo) << "\" (" << lo << ")\n";
}

int main() {
