import java.util.*;

public class Main {
    public static void main(String[] args) {
        String text = "ushers";
        String[] pats = {"he", "she", "his", "hers"};
        int max = 1;
        for (String p : pats) max += p.length();
        int[][] go = new int[max][26];             // go[v][c]: next state (0 = root)
        int[] fail = new int[max], end = new int[max], dict = new int[max];
        Arrays.fill(end, -1);
        int cnt = 1;
        for (int id = 0; id < pats.length; id++) { // 1) trie of all patterns
            int v = 0;
            for (char ch : pats[id].toCharArray()) {
                if (go[v][ch - 'a'] == 0) go[v][ch - 'a'] = cnt++;
                v = go[v][ch - 'a'];
            }
            end[v] = id;
        }
        int[] queue = new int[max];
        int head = 0, tail = 0;
        for (int c = 0; c < 26; c++) if (go[0][c] != 0) queue[tail++] = go[0][c];
        while (head < tail) {                      // 2) BFS: shallow states first
            int v = queue[head++];
            // dict[v]: nearest state on the fail chain where some pattern ends.
            dict[v] = end[fail[v]] >= 0 ? fail[v] : dict[fail[v]];
            for (int c = 0; c < 26; c++) {
                int u = go[v][c];
                if (u == 0) go[v][c] = go[fail[v]][c];           // missing edge: borrow from fail
                else { fail[u] = go[fail[v]][c]; queue[tail++] = u; }
            }
        }
        System.out.println("Text: " + text + ", patterns: " + String.join(" ", pats));
        int state = 0;
        for (int i = 0; i < text.length(); i++) {  // 3) one pass, one table lookup per letter
            state = go[state][text.charAt(i) - 'a'];
            for (int v = end[state] >= 0 ? state : dict[state]; v != 0; v = dict[v])
                System.out.println("  " + pats[end[v]] + " found at index " + (i - pats[end[v]].length() + 1));
        }
        System.out.println("Letters read: KMP per pattern = " + pats.length * text.length()
            + ", Aho-Corasick = " + text.length());
        // Build O(M * 26), scan O(N + matches); space O(M * 26). M = total pattern length.
    }
}

