public class Main {
    // Fold case and map everything that is not a letter to "space" (26).
    static int idx(char ch) {
        if (ch >= 'a' && ch <= 'z') return ch - 'a';
        if (ch >= 'A' && ch <= 'Z') return ch - 'A';
        return 26;
    }

    public static void main(String[] args) {
        String[] banned = {"bad", "darn it"};
        String message = "A badge is not BAD, darn it!";
        int max = 1;
        for (String p : banned) max += p.length() + 2;
        int[][] go = new int[max][27];
        int[] fail = new int[max], hit = new int[max];
        java.util.Arrays.fill(hit, -1);
        int cnt = 1;
        for (int id = 0; id < banned.length; id++) {
            int v = 0;
            // A space on both sides means "whole words only": " bad " is not inside " badge ".
            for (char ch : (" " + banned[id] + " ").toCharArray()) {
                if (go[v][idx(ch)] == 0) go[v][idx(ch)] = cnt++;
                v = go[v][idx(ch)];
            }
            hit[v] = id;
        }
        int[] queue = new int[max];
        int head = 0, tail = 0;
        for (int c = 0; c < 27; c++) if (go[0][c] != 0) queue[tail++] = go[0][c];
        while (head < tail) {
            int v = queue[head++];
            if (hit[v] < 0) hit[v] = hit[fail[v]];     // a phrase may end on the fail chain
            for (int c = 0; c < 27; c++) {
                int u = go[v][c];
                if (u == 0) go[v][c] = go[fail[v]][c];
                else { fail[u] = go[fail[v]][c]; queue[tail++] = u; }
            }
        }
        System.out.println("Message: " + message);
        int state = go[0][26];                         // the stream starts at a word boundary
        String stream = message + " ";                 // ...and ends at one
        for (int i = 0; i < stream.length(); i++) {
            state = go[state][idx(stream.charAt(i))];  // the whole per-character cost: one lookup
            if (hit[state] >= 0) System.out.println("after " + i + " characters: blocked \"" + banned[hit[state]] + "\"");
        }
        // Build once O(M * 27); each character O(1); per conversation: one int of state.
    }
}

