import java.util.*;

public class Main {
    static String s = "mississippi";
    static Integer[] sa;

    // First rank whose suffix (cut to p's length) is >= p, or > p when strict is true.
    static int bound(String p, boolean strict) {
        int lo = 0, hi = sa.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            String head = s.substring(sa[mid], Math.min(s.length(), sa[mid] + p.length()));
            int c = head.compareTo(p);
            if (c < 0 || (strict && c == 0)) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) {
        int n = s.length();
        sa = new Integer[n];
        for (int i = 0; i < n; i++) sa[i] = i;
        // Build the index once (naive sort here; real code uses O(N log N) doubling).
        Arrays.sort(sa, (a, b) -> s.substring(a).compareTo(s.substring(b)));
        System.out.println("Text: " + s);
        for (String p : new String[]{"ssi", "i", "sip", "xyz"}) {
            // All suffixes that start with p are neighbours in sorted order: one block [lo, hi).
            int lo = bound(p, false), hi = bound(p, true);
            System.out.println(p + ": " + (hi - lo) + " occurrence(s), ranks [" + lo + ", " + hi + ")");
        }
        // Each query: O(m log N) time, O(1) extra space. The index itself is N integers.
    }
}

