#include <bits/stdc++.h>
using namespace std;

string s = "mississippi";
vector<int> sa;

// First rank whose suffix (cut to p's length) is >= p, or > p when strict is true.
int bound(const string& p, bool strict) {
    int lo = 0, hi = sa.size();
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        int c = s.compare(sa[mid], p.size(), p);
        if (c < 0 || (strict && c == 0)) lo = mid + 1; else hi = mid;
    }
    return lo;
}

