    int n = s.size();
    sa.resize(n);
    iota(sa.begin(), sa.end(), 0);
    // Build the index once (naive sort here; real code uses O(N log N) doubling).
    sort(sa.begin(), sa.end(), [&](int a, int b) {
        return s.compare(a, string::npos, s, b, string::npos) < 0;
    });
    cout << "Text: " << s << "\n";
    for (string p : {"ssi", "i", "sip", "xyz"}) {
        // All suffixes that start with p are neighbours in sorted order: one block [lo, hi).
        int lo = bound(p, false), hi = bound(p, true);
