using System;

class Program {
    static string s = "mississippi";
    static int[] sa;

    // First rank whose suffix (cut to p's length) is >= p, or > p when strict is true.
    static int Bound(string p, bool strict) {
        int lo = 0, hi = sa.Length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            int c = string.CompareOrdinal(s, sa[mid], p, 0, p.Length);
            if (c < 0 || (strict && c == 0)) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    static void Main() {
        int n = s.Length;
        sa = new int[n];
        for (int i = 0; i < n; i++) sa[i] = i;
        // Build the index once (naive sort here; real code uses O(N log N) doubling).
        Array.Sort(sa, (a, b) => string.CompareOrdinal(s, a, s, b, n));
        Console.WriteLine("Text: " + s);
        foreach (string p in new string[] { "ssi", "i", "sip", "xyz" }) {
            // All suffixes that start with p are neighbours in sorted order: one block [lo, hi).
            int lo = Bound(p, false), hi = Bound(p, true);
            Console.WriteLine(p + ": " + (hi - lo) + " occurrence(s), ranks [" + lo + ", " + hi + ")");
        }
        // Each query: O(m log N) time, O(1) extra space. The index itself is N integers.
    }
}

