import java.util.*;

public class Main {
    // Way 1: put every substring in a set. O(N^3) time and memory, only for tiny inputs.
    static int brute(String s) {
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < s.length(); i++)
            for (int j = i + 1; j <= s.length(); j++) seen.add(s.substring(i, j));
        return seen.size();
    }

    // Way 3: N(N+1)/2 minus the sum of LCP values of neighbouring sorted suffixes.
    static void solve(String s) {
        int n = s.length();
        Integer[] sa = new Integer[n];
        for (int i = 0; i < n; i++) sa[i] = i;
        Arrays.sort(sa, (a, b) -> s.substring(a).compareTo(s.substring(b)));
        int shared = 0;
        for (int r = 1; r < n; r++) {
            // Prefixes this suffix shares with the one before it were already counted there.
            int a = sa[r - 1], b = sa[r], h = 0;
            while (a + h < n && b + h < n && s.charAt(a + h) == s.charAt(b + h)) h++;
            shared += h;
        }
        int all = n * (n + 1) / 2;               // every (start, end) pair
        System.out.println(s + ": set = " + brute(s) + ", suffix array = " + all + " - " + shared + " = " + (all - shared));
    }

    public static void main(String[] args) {
        for (String s : new String[]{"banana", "aaaa", "abcd"}) solve(s);
        // Formula: O(N log N) time and O(N) space with a fast suffix array and Kasai.
    }
}

