code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String text = "ababcbab";
        String[] words = {"ab", "bab", "b", "abc", "ab"};   // note the duplicate "ab"
        int max = 1;
        for (String w : words) max += w.length();
        int[][] go = new int[max][26];
        int[] fail = new int[max], node = new int[words.length];
        long[] visits = new long[max];
        int cnt = 1;
        for (int id = 0; id < words.length; id++) {
            int v = 0;
            for (char ch : words[id].toCharArray()) {
                if (go[v][ch - 'a'] == 0) go[v][ch - 'a'] = cnt++;
                v = go[v][ch - 'a'];
            }
            node[id] = v;                  // remember the word's end state (duplicates share it)
        }
        int[] order = new int[max];        // BFS order: shallow states first
        int head = 0, tail = 0;
        for (int c = 0; c < 26; c++) if (go[0][c] != 0) order[tail++] = go[0][c];
        while (head < tail) {
            int v = order[head++];
            for (int c = 0; c < 26; c++) {
                int u = go[v][c];
                if (u == 0) go[v][c] = go[fail[v]][c];
                else { fail[u] = go[fail[v]][c]; order[tail++] = u; }
            }
        }
        int state = 0;
        for (char ch : text.toCharArray()) {   // one scan: only count the state we land on
            state = go[state][ch - 'a'];
            visits[state]++;
        }
        // Deepest states first: a visit to v is also a visit to every suffix state fail[v].
        for (int i = tail - 1; i >= 0; i--) visits[fail[order[i]]] += visits[order[i]];
        System.out.println("Text: " + text);
        for (int id = 0; id < words.length; id++) System.out.println(words[id] + ": " + visits[node[id]]);
        // Time O(N + M * 26), space O(M * 26); no per-match work at all.
    }
}

